const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

const publicLinks = [
  ['home', 'Home'], ['pricing', 'Pricing'], ['sales', 'Sales'], ['about', 'About'], ['why-us', 'Why Refound'], ['quality', 'Quality'], ['faq', 'FAQ'],
];

const footerLinks = [
  ['pricing', 'Pricing'], ['sales', 'Sales & partnerships'], ['about', 'About us'], ['why-us', 'Why us'], ['quality', 'Quality & standards'], ['faq', 'FAQs'],
  ['terms', 'Terms & conditions'], ['privacy', 'Privacy policy'], ['copyright', 'Copyright & use'], ['contact', 'Contact us'],
];

export function renderPublicHeader(view, session) {
  return `<header class="public-header">
    <a class="brand" href="#" data-view="home" aria-label="Refound home">
      <img class="brand-symbol" src="./assets/refound-mark.png" alt="" />
      <span class="brand-copy"><span class="brand-name">REFOUND</span><span class="brand-tagline">From surplus to significance</span></span>
    </a>
    <nav class="public-nav" aria-label="Main navigation">${publicLinks.map(([key, label]) => `<button class="public-nav-link ${view === key ? 'active' : ''}" data-view="${key}">${label}</button>`).join('')}</nav>
    <div class="public-header-actions">${session ? `<button class="button button-outline public-sign-in" data-view="overview">My workspace</button><button class="public-signout" data-action="sign-out" aria-label="Sign out">↪</button>` : '<button class="button button-outline public-sign-in" data-view="login">Sign in</button><button class="button button-primary" data-view="signup">Join Refound <span>→</span></button>'}</div>
  </header>`;
}

function footer() {
  return `<footer class="public-footer"><div class="footer-brand"><a class="brand" href="#" data-view="home"><img class="brand-symbol" src="./assets/refound-mark.png" alt="" /><span class="brand-copy"><span class="brand-name">REFOUND</span><span class="brand-tagline">From surplus to significance</span></span></a><p>Good things, better futures.</p></div><div class="footer-link-grid">${footerLinks.map(([view, label]) => `<button data-view="${view}">${label}</button>`).join('')}<button data-view="assistant">AI assistant</button></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Refound. Demo product — not legal advice.</span><span>Built around care, trust, and less waste.</span></div></footer>`;
}

function publicLayout(body) {
  return `<div class="public-content">${body}</div>${footer()}`;
}

function heroChip(icon, label) {
  return `<span class="hero-chip"><i>${icon}</i>${label}</span>`;
}

