function login(context = {}) {
  const form = context.liveMode
    ? `<p>Your Refound organization account is managed by the configured secure sign-in provider.</p><button class="button button-primary button-large form-submit" data-action="live-login" data-url="${escapeHtml(context.loginPath ?? '/api/session')}">Continue securely <span>→</span></button><div class="demo-notice"><strong>Your account is not stored in this website.</strong><span>Your organization, role, and verification status come from the configured trusted identity provider and Odoo records.</span></div>`
    : `<p>Choose a demo portal. The prototype does not verify passwords or create real accounts.</p><form id="login-form" class="public-form"><label><span>Workspace</span><select name="role" id="login-role"><option value="company">Business partner</option><option value="ngo">Community organization / NGO</option><option value="admin">Refound administrator</option></select></label><label><span>Email</span><input name="email" type="email" placeholder="you@organization.org" value="morgan@meadowfig.demo" required /></label><label><span>Password</span><input name="password" type="password" placeholder="Demo only — any value" required /></label><button class="button button-primary button-large form-submit">Enter demo portal <span>→</span></button></form><div class="demo-notice"><strong>Demo mode, not real authentication.</strong><span>All three portals are available for trying the prototype. Admin access must be invitation-only in production.</span></div>`;
  return publicLayout(`<section class="auth-layout"><div class="auth-art"><div class="section-label">A LITTLE GOOD, READY TO GROW</div><h1>Good to have<br /><span>you back.</span></h1><p>Your community connections, handoffs, and impact—together in one place.</p><div class="auth-art-stamp">✳<span>Welcome<br />back</span></div></div><div class="auth-card"><div class="section-label">YOUR REFOUND PORTAL</div><h2>Sign in to your workspace</h2>${form}<p class="auth-switch">New to Refound? <button data-view="signup">Apply to join →</button></p></div></section>`);
}

