function verification(application, session, selectedRole, liveMode = false) {
  const role = session?.role === 'company' || session?.role === 'ngo' ? session.role : selectedRole === 'ngo' ? 'ngo' : 'company';
  const current = session ? application.find((item) => item.email === session.email) : null;
  const label = (status) => ({ pending: 'Under review', approved: 'Verified partner', rejected: 'Changes requested' }[status] ?? 'Not submitted');
  const currentPanel = current
    ? `<div class="verification-status-card status-${current.status}"><span class="status-emblem">${current.status === 'approved' ? '✓' : current.status === 'pending' ? '◷' : '!'}</span><div><strong>${label(current.status)}</strong><p>${escapeHtml(current.organizationName)} · Applied ${new Date(current.submittedAt).toLocaleDateString()}</p>${current.decisionNote ? `<p>Admin note: ${escapeHtml(current.decisionNote)}</p>` : ''}</div>${current.status === 'approved' ? '<span class="verified-badge">Verified ✓</span>' : ''}</div>`
    : '';
  return publicLayout(`<section class="subpage-intro"><div class="section-label">TRUST STARTS WITH PEOPLE</div><h1>Organization <span>verification.</span></h1><p>Tell us about your organization. A Refound administrator will review your application before partner actions are enabled.</p></section>
    <div class="verification-layout"><section class="verification-main">${currentPanel}<div class="verify-steps"><div class="verify-step"><i>1</i><span><strong>Share organization details</strong><small>Organization type, authorized contact, and registration.</small></span></div><span class="verify-connector"></span><div class="verify-step"><i>2</i><span><strong>Submit supporting documents</strong><small>Files are stored privately for reviewer access.</small></span></div><span class="verify-connector"></span><div class="verify-step"><i>3</i><span><strong>Human review &amp; decision</strong><small>An authorized Refound reviewer records a reason and decision.</small></span></div></div>
    <form id="verification-form" class="public-form verification-form" ${current && current.status !== 'rejected' ? 'hidden' : ''}><div class="section-label">ORGANIZATION APPLICATION</div><h2>${current ? 'Resubmit your details' : 'Tell us a little about you.'}</h2><div class="form-two"><label><span>Organization type</span><select name="organizationType" ${session ? 'disabled' : ''}><option value="company" ${role === 'company' ? 'selected' : ''}>Business / resource donor</option><option value="ngo" ${role === 'ngo' ? 'selected' : ''}>NGO / community organization</option></select></label><label><span>Registered organization name</span><input name="organizationName" value="${escapeHtml(current?.organizationName ?? session?.name ?? '')}" required maxlength="120" placeholder="Your organization’s name" /></label><label><span>Contact person</span><input name="contactName" value="${escapeHtml(current?.contactName ?? session?.contactName ?? '')}" required maxlength="100" placeholder="Authorized representative" /></label><label><span>Work email</span><input name="email" type="email" value="${escapeHtml(current?.email ?? session?.email ?? '')}" required maxlength="254" placeholder="you@organization.org" ${session ? 'readonly' : ''} /></label><label><span>City / delivery area</span><input name="location" value="${escapeHtml(current?.location ?? '')}" required maxlength="140" placeholder="City, service area, and receiving location" /></label><label><span>Official registration / charity number</span><input name="registrationId" value="${escapeHtml(current?.registrationId ?? '')}" required maxlength="80" placeholder="Government or charity register reference" /></label></div><label><span>Registration evidence and authorized-contact documents</span><input type="file" name="documents" accept=".pdf,.jpg,.jpeg,.png" multiple ${liveMode ? 'required' : ''} /><small class="form-help">PDF/JPG/PNG, up to 3 MB each. Uploads are restricted to the applicant and authorized reviewers.</small></label><div class="file-warning"><strong>${liveMode ? 'Private review process:' : 'Local demo only:'}</strong> ${liveMode ? 'Documents are stored as private Odoo attachments. An authorized reviewer must compare the registration and contact evidence against authoritative records; uploading documents alone does not verify identity.' : 'Files are not sent or stored; only filenames appear in the local demo queue. Do not select real identity documents.'}</div><label><span>Organization mission / service area</span><textarea name="notes" maxlength="700" rows="3" placeholder="Who you serve, operating region, and company or NGO contact context."></textarea></label><label class="consent-check"><input name="confirm" type="checkbox" required /><span>I confirm I’m authorized to submit these organization details and documents for verification.</span></label><div class="form-error" id="verification-error" role="alert"></div><button class="button button-primary button-large form-submit" type="submit">Submit for verification <span>→</span></button></form></section>
    <aside class="verification-aside"><span class="aside-icon">✳</span><div class="section-label">WHAT REVIEW MEANS</div><h2>Verification is a human identity and eligibility check.</h2><p>A reviewer examines registration details and supporting evidence, records a decision, and can request changes. Approved access is not a medical, food-safety, financial, or regulatory certification.</p><div class="aside-divider"></div><strong>Reviewer checklist</strong><ul><li>Check registration against the relevant official registry.</li><li>Confirm the contact is authorized to represent the organization.</li><li>Review submitted evidence securely and note any follow-up.</li><li>Approve, reject, or suspend access with a recorded reason.</li></ul><button class="text-button" data-view="quality">Read quality &amp; standards →</button></aside></div>`);
}

const faqs = [
  ['What is Refound?', 'Refound helps businesses share useful excess—including food, eligible medical equipment, study resources, and other essentials—with verified community organizations that need it.'],
  ['Who can sign up?', 'Businesses sharing eligible excess resources and community organizations can apply to become partners. A Refound administrator should review organization applications before live partner actions are available.'],
  ['How does verification work?', 'An organization submits its official registration number and supporting documents. Authorized Refound reviewers check the registration and representative, inspect the submitted evidence, and record an approval, rejection, or follow-up in the organization record. Verification does not certify resource safety.'],
  ['How are matches ranked?', 'The local demo considers urgency, category fit, freshness, and partner proximity. It also requires available surplus, an open request, and compatible quantity units. Suggestions explain the reason and should be confirmed with the receiving partner.'],
  ['Does Refound guarantee safety or collection?', 'No. A digital listing or match is not a product inspection, food-safety certification, medical recommendation, or guarantee of collection. Donors and recipient organizations must communicate and follow applicable laws for each resource type.'],
  ['Is the AI connected to a real model?', 'No. Text extraction and assistant answers currently use deterministic rules in your browser. No prompts are sent to an AI provider. A live AI integration needs a secure backend, privacy review, and human oversight.'],
  ['How much does Refound cost?', 'The proposed MVP membership is one month free, then AED 29/month for both businesses and NGOs. This demo does not charge you or start a subscription; checkout, billing terms, and cancellation controls still need to be built and reviewed.'],
  ['Is this connected to Odoo?', 'When the Refound backend is configured, organization applications, private verification documents, resource listings, community needs, orders, company delivery details, receipt confirmations, and order messages are persisted through the Odoo JSON-2 connector. Live mode requires Odoo 19+, the Refound Marketplace add-on, server-side credentials, and a trusted sign-in proxy.'],
  ['How do organizations get help?', 'Use Contact us to share a demo message or, for real support, the production team will need to publish a monitored contact address and response times.'],
];

function faq(liveMode = false) {
  const answers = liveMode ? faqs : faqs.map(([question, answer]) => question === 'How does verification work?'
    ? [question, 'In this local demo, organization applications and decisions are stored in browser storage and uploaded documents are not stored. Use test data only.']
    : question === 'Is this connected to Odoo?'
      ? [question, 'Not in this local demo server. Configure Odoo on the Refound server to use the server-side Odoo JSON-2 connector; credentials must never be added to browser code.']
      : [question, answer]);
  return publicLayout(`<section class="subpage-intro"><div class="section-label">A FEW GOOD QUESTIONS</div><h1>Curious? <span>That’s a good start.</span></h1><p>Clear answers about how Refound works—and what this deployment has connected.</p></section><section class="faq-layout"><div class="faq-list">${answers.map(([question, answer], index) => `<details class="faq-item" ${index === 0 ? 'open' : ''}><summary><span>${escapeHtml(question)}</span><i>＋</i></summary><p>${escapeHtml(answer)}</p></details>`).join('')}</div><aside class="faq-aside"><span>✳</span><h2>Still wondering?</h2><p>We’re building this with partners, not behind closed doors.</p><button class="button button-primary" data-view="contact">Contact us →</button></aside></section>`);
}

function contact() {
  return publicLayout(`<section class="subpage-intro"><div class="section-label">GOOD CONVERSATIONS START HERE</div><h1>Say hello. <span>We’re listening.</span></h1><p>Share a question, a partnership idea, or a note about what would help your community.</p></section><div class="contact-layout"><section class="contact-copy"><div class="contact-icon">✳</div><h2>Let’s find the right place to start.</h2><p>Our demo has no email service connected. Submitting this form shows a local confirmation only; it is not delivered to a support team.</p><div class="contact-method"><span>✉</span><div><strong>Production support</strong><small>A monitored Refound support contact needs to be added before launch.</small></div></div><div class="contact-method"><span>↗</span><div><strong>Business or NGO partner?</strong><small>Start with organization verification.</small></div></div><button class="text-button" data-view="verification">Apply to become a verified partner →</button></section><form id="contact-form" class="public-form contact-form"><div class="section-label">LOCAL DEMO FORM</div><label><span>Your name</span><input name="name" maxlength="100" required /></label><label><span>Email</span><input name="email" type="email" maxlength="254" required /></label><label><span>How can we help?</span><select name="subject"><option>Partnership</option><option>Product question</option><option>Food safety &amp; standards</option><option>Privacy request</option><option>Other</option></select></label><label><span>Message</span><textarea name="message" rows="4" maxlength="1200" required></textarea></label><div class="form-error" id="contact-error" role="alert"></div><button class="button button-primary button-large form-submit">Preview message <span>→</span></button><small class="local-only-note">Demo messages stay in this page and are not sent or stored.</small></form></div>`);
}

function assistant(messages = []) {
  const suggestions = ['How does verification work?', 'How are matches made?', 'Is this connected to Odoo?', 'How does Refound protect privacy?'];
  return publicLayout(`<section class="subpage-intro"><div class="section-label">A HELPFUL HAND, NOT A BLACK BOX</div><h1>Ask the Refound <span>assistant.</span></h1><p>Get help finding your way around. Demo replies are generated locally using fixed rules; no message is sent to an AI service.</p></section><section class="assistant-layout"><div class="assistant-card"><div class="assistant-head"><span class="assistant-avatar">✳</span><div><strong>Refound guide</strong><small><i></i> Local demo assistant · no live AI</small></div><span class="assistant-demo-tag">DEMO</span></div><div class="assistant-conversation"><div class="assistant-message"><span class="assistant-message-icon">✳</span><p>Hello! I can help explain verification, matching, privacy, and the planned Odoo connection. What would you like to know?</p></div>${messages.map((item) => `<div class="assistant-user-message"><strong>You</strong><p>${escapeHtml(item.question)}</p></div><div class="assistant-message"><span class="assistant-message-icon">✳</span><p>${escapeHtml(item.answer)}</p></div>`).join('')}</div><form id="assistant-form" class="assistant-input"><label class="visually-hidden" for="assistant-question">Ask the Refound assistant</label><textarea id="assistant-question" name="question" maxlength="500" rows="2" placeholder="Ask a question about Refound…" required></textarea><button class="button button-primary" aria-label="Ask assistant">Ask <span>→</span></button></form><div class="assistant-suggestions">${suggestions.map((item) => `<button data-action="ask-suggestion" data-question="${escapeHtml(item)}">${escapeHtml(item)} ↗</button>`).join('')}</div></div><aside class="assistant-boundary"><span>✳</span><h2>Helpful, with a human in the loop.</h2><p>Demo answers are informational. They cannot verify an organization, certify food, make legal decisions, or approve allocations.</p><button class="text-button" data-view="quality">Read our standards →</button></aside></section>`);
}

function organizationTypeLabel(type) {
  return type === 'ngo' ? 'NGO / community organization' : 'Business / resource donor';
}

function adminVerifications(applications, liveMode = false) {
  const pending = applications.filter((item) => item.status === 'pending');
  const documents = (item) => Array.isArray(item.documents) && item.documents.length
    ? item.documents.map((document, index) => typeof document === 'number'
      ? `<button class="document-preview-link" data-action="view-verification-document" data-application="${escapeHtml(item.id)}" data-document="${document}">↗ Open private document ${index + 1}</button>`
      : escapeHtml(document)).join(' · ')
    : 'No documents submitted';
  return `<section class="subpage-intro portal-intro"><div class="section-label">${liveMode ? 'ODOO REVIEW QUEUE' : 'ADMIN REVIEW QUEUE · DEMO'}</div><h1>Organization <span>verification.</span></h1><p>Review organization identity and documents before granting marketplace access. Check official registration and contact details; document submission alone does not verify an organization.</p>${liveMode ? '<div class="verification-review-guidance"><strong>Reviewer checklist</strong><span>Compare registration number with the relevant registry · validate authorized contact · examine uploaded supporting evidence · record the decision and reason.</span></div>' : '<div class="admin-demo-alert">⚠ Demo mode: application data is local. Production review requires authenticated reviewer roles and private Odoo attachment storage.</div>'}</section><div class="admin-queue-summary"><article><strong>${pending.length}</strong><span>Awaiting review</span></article><article><strong>${applications.filter((item) => item.status === 'approved').length}</strong><span>${liveMode ? 'Verified organizations' : 'Verified demo partners'}</span></article><article><strong>${applications.filter((item) => item.status === 'rejected').length}</strong><span>Declined</span></article></div><section class="admin-application-list">${pending.length ? pending.map((item) => `<article class="admin-application"><div class="application-heading"><span class="organization-type-icon ${item.organizationType === 'ngo' ? 'ngo' : ''}">${item.organizationType === 'ngo' ? '♡' : '↗'}</span><div><span class="application-type">${organizationTypeLabel(item.organizationType)}</span><h2>${escapeHtml(item.organizationName)}</h2><small>Submitted ${item.submittedAt ? new Date(item.submittedAt).toLocaleDateString() : 'recently'} · ${escapeHtml(item.location)}</small></div><span class="pending-pill">◷ Pending review</span></div><div class="application-details"><div><small>Primary contact</small><strong>${escapeHtml(item.contactName)}</strong></div><div><small>Email</small><strong>${escapeHtml(item.email)}</strong></div><div><small>Registration / charity no.</small><strong>${escapeHtml(item.registrationId || 'Not provided')}</strong></div><div><small>${liveMode ? 'Private Odoo documents · reviewer access' : 'Selected demo filenames (not uploaded)'}</small><strong>${documents(item)}</strong></div></div>${item.notes ? `<p class="application-note">${escapeHtml(item.notes)}</p>` : ''}<form id="review-form" class="review-form" data-application="${item.id}"><fieldset class="review-checklist"><legend>Confirm before approval</legend><label><input type="checkbox" name="registrationChecked" /><span>I checked the official registration / charity record.</span></label><label><input type="checkbox" name="authorityChecked" /><span>I confirmed this contact can represent the organization.</span></label><label><input type="checkbox" name="evidenceChecked" /><span>I reviewed the submitted evidence and noted any limitations.</span></label></fieldset><label><span>Reviewer note <small>${liveMode ? '(reason required for rejection)' : '(recommended for every decision)'}</small></span><input name="decisionNote" maxlength="1000" placeholder="What did you check? What needs follow-up?" /></label><div class="form-error review-error" role="alert"></div><div><button type="submit" class="button button-primary button-small" data-decision="approved">Approve partner <span>✓</span></button><button type="submit" class="button button-outline button-small reject-button" data-decision="rejected">Decline / request update</button></div></form></article>`).join('') : '<div class="empty-panel">You’re all caught up. New partner applications will appear here.</div>'}</section><div class="admin-footnote">${liveMode ? 'Every decision and checklist is written to the Odoo organization record. Verification establishes partner identity eligibility only; it does not certify resource safety.' : 'Demo decisions are local training flows and do not verify real organizations.'}</div>`;
}

function adminOrganizations(applications) {
  return `<section class="subpage-intro portal-intro"><div class="section-label">ADMIN DIRECTORY · DEMO</div><h1>Partner <span>organizations.</span></h1><p>See application status for demo partners. Private contact details belong in access-controlled backend screens, not a public directory.</p></section><div class="partner-directory">${applications.map((item) => `<article><span class="organization-type-icon ${item.organizationType === 'ngo' ? 'ngo' : ''}">${item.organizationType === 'ngo' ? '♡' : '↗'}</span><div><strong>${escapeHtml(item.organizationName)}</strong><small>${organizationTypeLabel(item.organizationType)} · ${escapeHtml(item.location)}</small></div><span class="verification-pill status-${item.status}">${item.status === 'approved' ? 'Verified' : item.status === 'pending' ? 'Awaiting review' : 'Declined'}</span></article>`).join('')}</div><div class="soft-callout warning-callout"><strong>Demo-only data</strong><p>This local directory has example organization records only. Production organizations and their contact details need verified Odoo/backend access controls.</p></div>`;
}

function adminSalesLeads(leads = []) {
  return `<section class="subpage-intro portal-intro"><div class="section-label">SALES INBOX · LOCAL DEMO</div><h1>Membership <span>enquiries.</span></h1><p>Local preview submissions about the Refound Membership. Nothing here has been emailed or sent to a CRM.</p><div class="admin-demo-alert">⚠ Demo sales inbox. Contact details live only in this browser and are not a real sales pipeline.</div></section><div class="admin-queue-summary"><article><strong>${leads.filter((lead) => lead.status === 'new').length}</strong><span>New demo enquiries</span></article><article><strong>${leads.filter((lead) => lead.status === 'contacted').length}</strong><span>Marked followed up</span></article><article><strong>AED 29</strong><span>Monthly plan · 1 month free</span></article></div><section class="admin-application-list">${leads.length ? leads.map((lead) => `<article class="admin-application"><div class="application-heading"><span class="organization-type-icon ${lead.organizationType === 'ngo' ? 'ngo' : ''}">${lead.organizationType === 'ngo' ? '♡' : '↗'}</span><div><span class="application-type">${lead.status === 'contacted' ? 'Followed up · demo' : 'New membership enquiry · demo'}</span><h2>${escapeHtml(lead.organization)}</h2><small>${escapeHtml(lead.organizationType === 'ngo' ? 'NGO / community organization' : 'Business')} · ${escapeHtml(lead.teamSize)} · Submitted ${new Date(lead.createdAt).toLocaleDateString()}</small></div><span class="verification-pill status-${lead.status === 'new' ? 'pending' : 'approved'}">${lead.status === 'new' ? 'New' : 'Followed up'}</span></div><div class="application-details"><div><small>Contact person</small><strong>${escapeHtml(lead.name)}</strong></div><div><small>Work email</small><strong>${escapeHtml(lead.email)}</strong></div><div><small>Interested in</small><strong>${escapeHtml(lead.plan)} · AED 29/month</strong></div><div><small>Offer</small><strong>One month free</strong></div></div><p class="application-note">${escapeHtml(lead.message)}</p><div class="review-form"><span class="admin-footnote">Demo only · no email sent</span><button class="button button-outline button-small" data-action="toggle-sales-lead" data-id="${escapeHtml(lead.id)}">${lead.status === 'contacted' ? 'Mark as new' : 'Mark followed up'}</button></div></article>`).join('') : '<div class="empty-panel">No demo sales enquiries yet. A submission from the Sales page will appear here.</div>'}</section>`;
}

export function renderPublicPage(view, context = {}) {
  if (view === 'home') return home();
  if (view === 'pricing') return pricing();
  if (view === 'sales') return sales(context.liveMode);
  if (view === 'login') return login(context);
  if (view === 'signup') return signup();
  if (view === 'verification') return verification(context.applications ?? [], context.session, context.verificationRole, context.liveMode);
  if (view === 'faq') return faq(context.liveMode);
  if (view === 'contact') return contact();
  if (view === 'assistant') return assistant(context.assistantMessages ?? []);
  if (view === 'admin-verifications') return publicLayout(adminVerifications(context.applications ?? [], context.liveMode));
  if (view === 'admin-organizations') return publicLayout(adminOrganizations(context.applications ?? []));
  if (view === 'admin-sales-leads') return publicLayout(adminSalesLeads(context.leads ?? []));
  const info = infoPages[view] ?? infoPages.about;
  const body = view === 'quality' && context.liveMode
    ? info.body.replace('Demo limitation</strong><p>This prototype does not inspect documents, verify identities, certify resource quality, or connect to regulatory databases. Demo application uploads remain on your device only as selected filenames.', 'Resource-safety boundary</strong><p>Authorized reviewers inspect private Odoo-stored registration evidence and record an organization verification decision. Verification does not certify food quality, medical devices, recalled-product status, or compliance with every regulatory database. Resource donors still provide accurate dates, condition, recall, and handling declarations; verify high-risk categories with the relevant authority.')
    : view === 'privacy' && context.liveMode
      ? info.body.replace('This prototype stores sample listings, requests, transfers, verification statuses, and selected document filenames in local browser storage so its demo flows work. It does not upload selected verification documents to a server. Browser data is not encrypted by this app, may remain on a shared device, and can be removed by clearing site data or resetting the demo.', 'In Odoo mode, the configured backend stores organization applications, private verification attachments, resources, requirements, orders, delivery events, and messages in the connected Odoo database. Access uses the trusted identity proxy and a server-side Odoo service account. The database operator must publish actual hosting, retention, backup, residency, access, and deletion details before launch.')
        .replace('Demo sign-in is not authentication. It does not verify identity, authorize a real Odoo account, send contact requests, or send assistant prompts to an AI provider. Do not use it for real beneficiary, donor, employee, identity-document, payment, health, or other sensitive data.', 'Odoo deployments authenticate through the configured trusted identity proxy, and the backend authorizes each role against a verified organization record. Do not enter any personal, payment, health, or identity data until your Odoo host, access controls, retention, backups, and incident response are approved for the data.')
      : view === 'why-us' && context.liveMode
        ? info.body.replace('The current experience is a local demo. Verification, identity checks, AI, privacy policies, and Odoo data need secure production services before public launch.', 'This deployment stores partner operations in its configured Odoo database, routes organization evidence for human review, and keeps delivery company-managed. AI remains a local deterministic helper until a reviewed server-side AI provider is configured.')
      : info.body;
  return publicLayout(`<section class="subpage-intro"><div class="section-label">${info.eyebrow}</div><h1>${info.title}</h1><p>${info.lead}</p></section><section class="info-page-body">${body}</section>`);
}
